const test = require("node:test");
const assert = require("node:assert");

const { CircuitBreaker, CircuitOpenError } = require("./breaker");

function boom() {
  throw new Error("boom");
}

test("trips open after consecutive failures", () => {
  const b = new CircuitBreaker(3, 10);
  for (let i = 0; i < 3; i++) {
    assert.throws(() => b.call(boom, 0), /boom/);
  }
  assert.throws(() => b.call(() => "should not run", 0), CircuitOpenError);
});

test("fails fast without calling fn while open", () => {
  const b = new CircuitBreaker(1, 100);
  assert.throws(() => b.call(boom, 0), /boom/);
  const calls = [];
  assert.throws(() => b.call(() => calls.push(1), 1), CircuitOpenError);
  assert.deepStrictEqual(calls, []);
});

test("half-open trial after timeout success closes", () => {
  const b = new CircuitBreaker(1, 10);
  assert.throws(() => b.call(boom, 0), /boom/);
  assert.strictEqual(b.call(() => "ok", 10), "ok");
  assert.strictEqual(b.call(() => "still-fine", 11), "still-fine");
});

test("half-open failure reopens and resets clock", () => {
  const b = new CircuitBreaker(1, 10);
  assert.throws(() => b.call(boom, 0), /boom/);
  assert.throws(() => b.call(boom, 10), /boom/);
  assert.throws(() => b.call(() => "too soon", 15), CircuitOpenError);
  assert.strictEqual(b.call(() => "ok now", 20), "ok now");
});

