class CircuitOpenError extends Error {}

class CircuitBreaker {
  constructor(failureThreshold, resetTimeout) {
    this.failureThreshold = failureThreshold;
    this.resetTimeout = resetTimeout;
    this.state = "closed";
    this.failures = 0;
    this.openedAt = null;
  }

  call(fn, now) {
    if (this.state === "open") {
      if (now - this.openedAt < this.resetTimeout) {
        throw new CircuitOpenError();
      }
      this.state = "half_open";
    }

    let result;
    try {
      result = fn();
    } catch (err) {
      if (this.state === "half_open") {
        this.state = "open";
        this.openedAt = now;
      } else {
        this.failures += 1;
        if (this.failures >= this.failureThreshold) {
          this.state = "open";
          this.openedAt = now;
        }
      }
      throw err;
    }

    this.state = "closed";
    this.failures = 0;
    return result;
  }
}

module.exports = { CircuitBreaker, CircuitOpenError };

